const app=document.querySelector('#app');let data,state={step:0,mode:'broad_exploration',state:'',online:false,maxPrice:'',affordability:0,career:0,selected:new Set()};const money=v=>v==null?'Evidence unavailable':`$${Number(v).toLocaleString()}`;function steps(){document.querySelectorAll('#steps li').forEach((x,i)=>x.classList.toggle('active',i===state.step))}function next(){state.step++;render()}function back(){state.step--;render()}function eligible(c){if(state.state&&c.state!==state.state)return false;if(state.online&&!c.online)return false;if(state.maxPrice&&c.net_price!=null&&c.net_price>+state.maxPrice)return false;return true}function start(){app.innerHTML=`<div class="panel"><h2>What are you trying to decide?</h2><label for="mode">Starting point</label><select id="mode"><option value="broad_exploration">Explore colleges, programs, and careers together</option><option value="career_first">Start with careers that may fit me</option><option value="college_program_first">Find colleges for a program I have in mind</option><option value="compare_known">Compare programs I already know</option><option value="transfer">Plan a transfer</option><option value="returning_student">Return to college or finish a degree</option></select><button id="next">Continue</button></div>`;mode.value=state.mode;mode.onchange=e=>state.mode=e.target.value;next.onclick=()=>next()}function must(){app.innerHTML=`<div class="panel"><h2>Your must-haves</h2><p class="note">Unknown evidence stays visible rather than being treated as a mismatch.</p><label>School state</label><select id="st"><option value="">No requirement</option><option>NY</option><option>NJ</option></select><label><input id="on" type="checkbox" style="width:auto"> Must be available online</label><label>Maximum annual net price</label><input id="price" type="number" min="0" placeholder="No firm ceiling"><p class="note">Net price is not tuition or total cost of attendance.</p><button id="prev" class="secondary">Back</button><button id="go">Continue</button></div>`;st.value=state.state;on.checked=state.online;price.value=state.maxPrice;prev.onclick=back;go.onclick=()=>{state.state=st.value;state.online=on.checked;state.maxPrice=price.value;next()}}function priorities(){app.innerHTML=`<div class="panel"><h2>What matters most?</h2><p>Skip anything that is not important to you. This prototype does not assign default weights.</p><label>Keeping costs low: <span id="av">${state.affordability||'skip'}</span></label><input id="a" type="range" min="0" max="5" value="${state.affordability}"><label>Career pathways and outlook: <span id="cv">${state.career||'skip'}</span></label><input id="c" type="range" min="0" max="5" value="${state.career}"><button id="prev" class="secondary">Back</button><button id="go">Find matches</button></div>`;a.oninput=()=>av.textContent=a.value==0?'skip':a.value;c.oninput=()=>cv.textContent=c.value==0?'skip':c.value;prev.onclick=back;go.onclick=()=>{state.affordability=+a.value;state.career=+c.value;next()}}function matches(){let rows=data.candidates.filter(eligible);app.innerHTML=`<h2>Matched programs</h2><p>${rows.length} synthetic candidates meet the evaluated must-haves. Results are not presented as a universal rank.</p><div class="grid">${rows.map(c=>`<article class="card"><h3>${c.program}</h3><p>${c.institution} · ${c.state}</p><div class="metric"><strong>Annual net price</strong><br>${money(c.net_price)}</div><div class="metric"><strong>Career pathways</strong><br>${c.careers.map(x=>`<span class="tag">${x}</span>`).join('')}</div><div class="metric"><strong>Current-market median wage</strong><br><span class="${c.current_market.state==='missing'?'unknown':''}">${money(c.current_market.median_wage)}</span></div><div class="metric"><strong>Long-term outlook</strong><br>${c.outlook.change_pct}% projected change through ${c.outlook.year}</div><label><input class="pick" data-id="${c.candidate_id}" type="checkbox" style="width:auto" ${state.selected.has(c.candidate_id)?'checked':''}> Compare this program</label></article>`).join('')}</div><button id="prev" class="secondary">Change priorities</button><button id="cmp">Compare selected</button>`;document.querySelectorAll('.pick').forEach(x=>x.onchange=()=>x.checked?state.selected.add(x.dataset.id):state.selected.delete(x.dataset.id));prev.onclick=back;cmp.onclick=()=>{if(state.selected.size<2)return alert('Select at least two programs to compare.');next()}}function compare(){let cs=data.candidates.filter(c=>state.selected.has(c.candidate_id));app.innerHTML=`<h2>Compare programs</h2><p class="note">No automatic winner. Missing evidence is not zero, and current-market evidence is distinct from long-term outlook.</p><div class="compare"><table><thead><tr><th>Evidence</th>${cs.map(c=>`<th>${c.program}<br><small>${c.institution}</small></th>`).join('')}</tr></thead><tbody><tr><th>Net price</th>${cs.map(c=>`<td>${money(c.net_price)}</td>`).join('')}</tr><tr><th>Program earnings</th>${cs.map(c=>`<td>${money(c.earnings)}</td>`).join('')}</tr><tr><th>Transfer</th>${cs.map(c=>`<td>${c.transfer||'Evidence unavailable'}</td>`).join('')}</tr><tr><th>Career pathways</th>${cs.map(c=>`<td>${c.careers.join(', ')}</td>`).join('')}</tr><tr><th>Current-market wage</th>${cs.map(c=>`<td>${money(c.current_market.median_wage)}</td>`).join('')}</tr><tr><th>Long-term outlook</th>${cs.map(c=>`<td>${c.outlook.change_pct}% through ${c.outlook.year}</td>`).join('')}</tr></tbody></table></div><button id="prev" class="secondary">Back to matches</button><button id="restart">Change my answers</button>`;prev.onclick=back;restart.onclick=()=>{state.step=1;render()}}function render(){steps();[start,must,priorities,matches,compare][state.step]()}fetch('fixtures.json').then(r=>r.json()).then(x=>{data=x;render()});